namespace GeetaStudio.Api;

public static class WatchPage
{
    public const string Html = """
<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WATCH episode studio</title>
<style>body{font:1rem system-ui;max-width:72rem;margin:2rem auto;padding:1rem;color:#243e35}label{display:block;margin:.7rem 0}input,select,textarea,button{font:inherit;min-height:44px;padding:.6rem;max-width:100%;box-sizing:border-box}section,article{border:1px solid #9aafa1;padding:1rem;margin:1rem 0}video{width:100%;max-height:42rem;background:#243e35}textarea{width:100%;min-height:8rem}pre{white-space:pre-wrap;overflow-wrap:anywhere}:focus-visible{outline:3px solid #ad5d10}</style>
<h1>WATCH episode studio</h1><p>Turn a reviewed story and approved character media into an original captioned episode. Technical checks and a local preview do not approve public release.</p>
<p><a href="/staff/editorial">Script review</a> · <a href="/staff/characters">Characters</a> · <a href="/staff/media">Pictures and voices</a></p>
<label>Workspace code <input id="tenant"></label><label>Universe code <input id="universe"></label><button id="load">Open episode studio</button><p role="status" id="status"></p>
<section><h2>Layout and renderer setup</h2><label>Layout name <input id="templateName" value="original-caption-layout"></label><button id="addTemplate">Add layout for review</button><label>Reviewed layout <select id="template"></select></label><button id="reviewTemplate">Review selected layout</button><label>Renderer profile name <input id="profileName" value="local-original-episodes"></label><label>Renderer <select id="renderer"><option value="watch.ffmpeg.v1">Local video composition</option><option value="watch.ffmpeg.test-b.v1">Second composition adapter</option><option value="watch.fail-once.v1">Controlled failure recovery fixture</option><option value="watch.unknown.v1">Controlled reconciliation fixture</option></select></label><button id="addProfile">Register renderer profile</button></section>
<section><h2>Prepare an episode</h2><label>Approved script <select id="script"></select></label><button id="showScript">Read selected script</button><pre id="scriptText"></pre><label>Episode name <input id="episodeName"></label><label>Renderer profile <select id="profile"></select></label><label>Exact approved character presentation <select id="presentation"></select></label><label>Reviewed picture <select id="image"></select></label><label>Reviewed spoken recording <select id="voice"></select></label><label>Recording/transcript evidence <input id="transcript" value="fixture:controlled-preview-not-public"></label><label>Shape <select id="aspect"><option value="Both">Vertical short and standard</option><option>Vertical</option><option>Standard</option></select></label><button id="create">Prepare single-scene episode</button><p>Longer scripts use the storyboard request below. Every scene must cover the approved script in order; missing context and unsupported timing are blocked.</p></section>
<section><h2>Final review</h2><label>Review type <select id="mode"><option>Fixture</option><option>Manual</option></select></label><label>Evidence reference <input id="evidence" value="fixture:technical-preview-human-release-pending"></label><label>Unresolved visual, sound, pronunciation or caption issues <textarea id="deviations"></textarea></label><label>Minutes actually spent reviewing <input id="minutes" type="number" min="1" max="600" value="1"></label><p>Manual/public approval still needs genuine script, source and media qualification. A changed renderer or corrected episode has its own QA and review.</p></section>
<section><h2>Episodes and playable previews</h2><div id="episodes"></div></section>
<details><summary>Multi-scene storyboard administration</summary><label>Owned CreateWatch request <textarea id="request" spellcheck="false">{}</textarea></label><button id="advanced">Prepare reviewed storyboard</button></details>
<script>
const get=id=>document.getElementById(id),scope=()=>'/tenants/'+encodeURIComponent(get('tenant').value)+'/universes/'+encodeURIComponent(get('universe').value),base=()=>'/api/v1/watch'+scope();let scripts=[],templates=[],profiles=[],presentations=[],versions=[],selectedScript=null;
async function call(path,data){const r=await fetch(path,{method:data?'POST':'GET',credentials:'same-origin',cache:'no-store',headers:data?{'Content-Type':'application/json','X-ContentOS-Staff':'1'}:{},body:data?JSON.stringify(data):undefined});if(!r.ok)throw Error(await r.text());return r.status===204?null:await r.json();}
function options(id,rows,key,label){get(id).replaceChildren();for(const row of rows){const o=document.createElement('option');o.value=key(row);o.textContent=label(row);get(id).append(o);}}
function button(label,parent,action){const b=document.createElement('button');b.textContent=label;b.onclick=()=>run(action);parent.append(b);}
async function run(action){try{await action();await load();}catch(e){get('status').textContent=e.message;}}
function review(row,decision){return {operationId:crypto.randomUUID(),expectedRowVersion:row.rowVersion,decision,mode:get('mode').value,evidenceReference:get('evidence').value,deviations:get('deviations').value.split('\n').filter(x=>x.trim()),reviewMinutes:Number(get('minutes').value)};}
function mediaChoices(){const p=presentations.find(x=>x.id===get('presentation').value);for(const id of ['image','voice'])options(id,versions.filter(v=>p&&v.characterProfileRevisionId===p.rules.profileRevisionId&&v.reviewStatus==='Approved'&&v.blocks.length===0&&v.info.mime===(id==='image'?'image/png':'audio/wav')),v=>v.id,v=>v.accessibilityDescription);}
async function load(){try{templates=await call(base()+'/templates');profiles=await call(base()+'/profiles');scripts=await call('/api/v1/editorial'+scope()+'/items');presentations=await call('/api/v1/registry'+scope()+'/presentations');versions=(await call('/api/v1/media'+scope()+'/assets')).flatMap(x=>x.versions);options('template',templates,x=>x.id,x=>x.configuration.key+' · '+x.reviewStatus);options('profile',profiles.filter(x=>x.enabled),x=>x.id,x=>x.configuration.key);options('script',scripts.filter(x=>['Approved','Scheduled','Published'].includes(x.state)),x=>x.id,x=>x.key);options('presentation',presentations.filter(x=>x.reviewStatus==='Approved'),x=>x.id,x=>x.rules.style);mediaChoices();const episodes=await call(base()+'/productions');get('episodes').replaceChildren();for(const p of episodes){const a=document.createElement('article');get('episodes').append(a);const title=document.createElement('h3');title.textContent=p.key+' · version '+p.version+' · '+p.state;a.append(title);const notes=document.createElement('p');notes.textContent='Creation cost '+p.creationCost+' '+p.currency+' · Review effort '+p.reviewMinutes+' min · '+p.blocks.join('; ');a.append(notes);for(const asset of p.artifacts){const label=document.createElement('p');label.textContent=asset.aspect+' · '+asset.warnings.join('; ');a.append(label);const video=document.createElement('video');video.controls=true;video.preload='metadata';video.src=base()+'/artifacts/'+asset.id+'/preview';const track=document.createElement('track');track.kind='captions';track.label='Approved script';track.srclang=p.timeline?.locale||'en';track.src=base()+'/productions/'+p.id+'/captions.vtt';track.default=true;video.append(track);a.append(video);}for(const action of ['Resume','Reconcile','Cancel','Withdraw'])button(action,a,()=>call(base()+'/productions/'+p.id+'/control',{operationId:crypto.randomUUID(),expectedRowVersion:p.rowVersion,action,evidenceReference:get('evidence').value}));button('Approve final episode',a,()=>call(base()+'/productions/'+p.id+'/review',review(p,'Approve')));button('Reject for correction',a,()=>call(base()+'/productions/'+p.id+'/review',review(p,'Reject')));button('Download manifest and captions',a,async()=>{const result=await call(base()+'/productions/'+p.id+'/export');const blob=URL.createObjectURL(new Blob([JSON.stringify(result,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=blob;link.download='episode-package.json';link.click();URL.revokeObjectURL(blob);});const d=document.createElement('details');const summary=document.createElement('summary');summary.textContent='Evidence, frozen cast and stage checkpoints';const pre=document.createElement('pre');pre.textContent=JSON.stringify({timeline:p.timeline,stages:p.stages},null,2);d.append(summary,pre);a.append(d);}get('status').textContent='Current episode checkpoints and media loaded.';}catch(e){get('status').textContent=e.message;}}
get('load').onclick=load;get('presentation').onchange=mediaChoices;
get('addTemplate').onclick=()=>run(()=>call(base()+'/templates',{operationId:crypto.randomUUID(),key:get('templateName').value,version:1,rules:{frameRate:24,captionSize:28,safeMarginPercent:10,font:'Nirmala UI',background:'#243E35',creditSeconds:5}}));get('reviewTemplate').onclick=()=>run(()=>call(base()+'/templates/'+get('template').value+'/review',review(templates.find(x=>x.id===get('template').value),'Approve')));
get('addProfile').onclick=()=>run(()=>call(base()+'/profiles',{operationId:crypto.randomUUID(),key:get('profileName').value,version:1,renderer:get('renderer').value,accountReference:'local:owned-renderer',templateId:get('template').value,callCeiling:0,currency:'INR',mode:get('mode').value,evidenceReference:get('evidence').value}));
get('showScript').onclick=async()=>{try{selectedScript=await call('/api/v1/editorial'+scope()+'/items/'+get('script').value);get('scriptText').textContent=selectedScript.current?.body||'Script withheld; review current rights.';}catch(e){get('status').textContent=e.message;}};
get('create').onclick=()=>run(async()=>{const p=presentations.find(x=>x.id===get('presentation').value);const script=await call('/api/v1/editorial'+scope()+'/items/'+get('script').value);if(!script.current||script.current.body.length>160)throw Error('Use a complete multi-scene storyboard for a longer script.');const characters=await call('/api/v1/registry'+scope()+'/characters');const character=characters.find(x=>x.profile.id===p.rules.profileRevisionId);await call(base()+'/productions',{operationId:crypto.randomUUID(),key:get('episodeName').value,version:1,editorialItemId:script.id,profileId:get('profile').value,scenes:[{key:'scene-1',scriptStart:0,scriptLength:script.current.body.length,characterId:character.characterId,presentationId:p.id,imageVersionId:get('image').value,voiceVersionId:get('voice').value,transcriptEvidenceReference:get('transcript').value}],aspects:get('aspect').value==='Both'?['Vertical','Standard']:[get('aspect').value],maxMediaCost:0,deadlineSeconds:300});});get('advanced').onclick=()=>run(()=>call(base()+'/productions',JSON.parse(get('request').value)));
</script></html>
""";
}
